import { Group, Mesh, PlaneGeometry, MeshStandardNodeMaterial, Color, Vector2, PointLight } from 'three/webgpu';
import { uv, texture, uniform, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const spec = config.intent?.visualSpec ?? {};
  const colors = config.colors ?? spec.colors ?? {};
  const inkHex = colors.ink ?? '#16161d';
  const paperHex = colors.paper ?? '#e8ecf2';
  const accentHex = colors.accent ?? '#ff2a38';
  const surfaceHex = colors.surface ?? '#0b0b10';

  const group = new Group();
  group.name = 'hub-features-card-0';

  const rowW = 3.0;
  const rowH = 0.55;

  // ---- Backdrop panel (row surface) ----
  const panelMat = new MeshStandardNodeMaterial({
    color: new Color(surfaceHex),
    roughness: 0.72,
    metalness: 0.22,
  });
  const panelGeo = new PlaneGeometry(rowW, rowH);
  const panel = new Mesh(panelGeo, panelMat);
  panel.position.z = -0.04;
  group.add(panel);

  // ---- Parallax image plane with depth displacement ----
  const planeGeo = new PlaneGeometry(rowW, rowH, 96, 24);

  const colorTexUniform = uniform(null);
  const depthTexUniform = uniform(null);
  const mouseU = uniform(new Vector2(0, 0));
  const parallaxStrength = uniform(0.025);
  const dispStrength = uniform(0.05);

  const imgMat = new MeshStandardNodeMaterial();
  imgMat.roughness = 0.5;
  imgMat.metalness = 0.18;
  imgMat.color = new Color(0xffffff);
  imgMat.transparent = true;
  imgMat.opacity = 0;

  // Parallax-shifted UV for color sampling
  const offsetUV = uv().add(mouseU.mul(parallaxStrength));
  imgMat.colorNode = texture(colorTexUniform, offsetUV);

  // Depth-displaced vertex position
  const depthVal = texture(depthTexUniform, uv()).r;
  imgMat.positionNode = vec3(
    uv().x.mul(rowW).sub(rowW * 0.5),
    uv().y.mul(rowH).sub(rowH * 0.5),
    depthVal.mul(dispStrength)
  );

  const imgPlane = new Mesh(planeGeo, imgMat);
  imgPlane.position.z = 0.0;
  group.add(imgPlane);

  // ---- Subtle divider (bottom) ----
  const dividerMat = new MeshStandardNodeMaterial({
    color: new Color(accentHex),
    emissive: new Color(accentHex),
    emissiveIntensity: 0.35,
    roughness: 0.4,
    metalness: 0.5,
    transparent: true,
    opacity: 0.55,
  });
  const dividerGeo = new PlaneGeometry(rowW * 0.92, 0.006);
  const divider = new Mesh(dividerGeo, dividerMat);
  divider.position.set(0, -rowH * 0.42, 0.001);
  group.add(divider);

  // ---- Accent strip (focus/hover indicator) ----
  const stripMat = new MeshStandardNodeMaterial({
    color: new Color(accentHex),
    emissive: new Color(accentHex),
    emissiveIntensity: 0.0,
    roughness: 0.5,
    metalness: 0.4,
  });
  const stripGeo = new PlaneGeometry(0.04, rowH * 0.8);
  const strip = new Mesh(stripGeo, stripMat);
  strip.position.set(-rowW * 0.48, 0, 0.002);
  group.add(strip);

  // ---- Node-local rim light (accent hue) ----
  const rimLight = new PointLight(new Color(accentHex), 0.7, 6);
  rimLight.position.set(2.0, 0.4, 1.4);
  group.add(rimLight);

  // ---- Load textures ----
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.minFilter = THREE.LinearFilter;
      tex.magFilter = THREE.LinearFilter;
      colorTexUniform.value = tex;
    });
  }
  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      tex.colorSpace = THREE.NoColorSpace;
      tex.minFilter = THREE.LinearFilter;
      tex.magFilter = THREE.LinearFilter;
      depthTexUniform.value = tex;
    });
  }

  // ---- Entrance timeline (rise-in + weighted-settle) ----
  const timeline = gsap.timeline();
  timeline.fromTo(group.position, { y: 0.4 }, { y: 0, duration: 0.7, ease: 'power3.out' }, 0);
  timeline.fromTo(group.scale, { x: 0.96, y: 0.96 }, { x: 1.04, y: 1.04, duration: 0.7, ease: 'power3.out' }, 0);
  timeline.to(group.scale, { x: 1.0, y: 1.0, duration: 0.9, ease: 'power4.out' }, 0.7);
  timeline.fromTo(imgMat, { opacity: 0 }, { opacity: 1, duration: 0.6, ease: 'power2.out' }, 0.1);

  // ---- Interactions ----
  let liftTween = null;
  let pressTween = null;
  let stripTween = null;
  let mouseTween = null;
  const baseY = 0;

  const handlers = {
    hover() {
      if (liftTween) liftTween.kill();
      liftTween = gsap.to(group.position, { y: baseY + 0.15, duration: 0.5, ease: 'power3.out' });
      if (stripTween) stripTween.kill();
      stripTween = gsap.to(stripMat, { emissiveIntensity: 1.3, duration: 0.3, ease: 'power2.out' });
    },
    hoverEnd() {
      if (liftTween) liftTween.kill();
      liftTween = gsap.to(group.position, { y: baseY, duration: 0.5, ease: 'power3.out' });
      if (stripTween) stripTween.kill();
      stripTween = gsap.to(stripMat, { emissiveIntensity: 0.0, duration: 0.3, ease: 'power2.out' });
    },
    click() {
      if (pressTween) pressTween.kill();
      pressTween = gsap.timeline()
        .to(group.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.in(2)' })
        .to(group.scale, { x: 1.0, y: 1.0, duration: 0.4, ease: 'elastic.out(1, 0.4)' });
      ctx.emit('navigate', { to: 'hub-features' });
      ctx.emit('hub-features.select', {});
    },
    pointermove(e) {
      const nx = (e && typeof e.pointerNDC?.x === 'number') ? e.pointerNDC.x : 0;
      const ny = (e && typeof e.pointerNDC?.y === 'number') ? e.pointerNDC.y : 0;
      if (mouseTween) mouseTween.kill();
      mouseTween = gsap.to(mouseU.value, { x: -nx, y: -ny, duration: 0.6, ease: 'power2.out' });
    },
  };

  group.userData.handlers = handlers;

  group.userData.cleanup = () => {
    timeline.kill();
    if (liftTween) liftTween.kill();
    if (pressTween) pressTween.kill();
    if (stripTween) stripTween.kill();
    if (mouseTween) mouseTween.kill();
    panelGeo.dispose();
    planeGeo.dispose();
    dividerGeo.dispose();
    stripGeo.dispose();
    panelMat.dispose();
    imgMat.dispose();
    dividerMat.dispose();
    stripMat.dispose();
    rimLight.dispose && rimLight.dispose();
  };

  return group;
}
